  var expected=jdbc.queryForList("select id from treatment_plan where clinic_id=? and removed_at is null order by created_at desc,id desc",UUID.class,clinic);assertEquals(expected,plans.discoverByClinic(clinic,0,20,null,TreatmentPlanStatus.DRAFT).content().stream().map(ClinicTreatmentPlanSummary::id).toList());
