 @org.junit.jupiter.params.ParameterizedTest
 @org.junit.jupiter.params.provider.ValueSource(strings={"invoice","invoiceItem","material","consentPlan","consentItem","followUpPlan","followUpItem"})
 void everyProtectedReferenceBlocksRemovalIncludingRemovedItems(String kind){
  var p=plan();var i=item(p.getId());entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Earlier removal"));
  if(kind.startsWith("invoice")){UUID invoice=UUID.randomUUID();jdbc.update("insert into invoice(id,clinic_id,patient_id,invoice_number,treatment_plan_id) values (?,?,?,?,?)",invoice,clinic,patient,invoice.toString(),kind.equals("invoice")?p.getId():null);if(kind.equals("invoiceItem"))jdbc.update("insert into invoice_item(clinic_id,invoice_id,treatment_plan_item_id,item_name_snapshot) values (?,?,?,'Snapshot')",clinic,invoice,i.getId());}
  else if(kind.startsWith("consent"))jdbc.update("insert into patient_consent(clinic_id,patient_id,consent_number,consent_title_snapshot,consent_text_snapshot,treatment_plan_id,treatment_plan_item_id) values (?,?,?,'Consent','Text',?,?)",clinic,patient,UUID.randomUUID().toString(),kind.equals("consentPlan")?p.getId():null,kind.equals("consentItem")?i.getId():null);
  else if(kind.startsWith("followUp"))jdbc.update("insert into patient_follow_up(clinic_id,patient_id,scheduled_date,treatment_plan_id,treatment_plan_item_id) values (?,?,current_date,?,?)",clinic,patient,kind.equals("followUpPlan")?p.getId():null,kind.equals("followUpItem")?i.getId():null);
  else {UUID stock=UUID.randomUUID(),batch=UUID.randomUUID();jdbc.update("insert into inventory_item(id,clinic_id,item_code,item_name) values (?,?,?,'Test stock')",stock,clinic,stock.toString());jdbc.update("insert into inventory_batch(id,clinic_id,inventory_item_id,quantity_received,current_quantity) values (?,?,?,1,1)",batch,clinic,stock);jdbc.update("insert into patient_material_usage(clinic_id,patient_id,treatment_plan_item_id,inventory_item_id,inventory_batch_id,quantity_used,used_by) values (?,?,?,?,?,1,?)",clinic,patient,i.getId(),stock,batch,user);}
  long before=revision(p.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->removePlan(p.getId())).status);assertEquals(before,revision(p.getId()));assertNull(jdbc.queryForObject("select removed_at from treatment_plan where id=?",java.sql.Timestamp.class,p.getId()));
 }
