 @Test void removePopulatedDraftRetainsAllItemsAndFinalizedOrigin(){var p=plan();var active=item(p.getId());var removed=item(p.getId());entries.remove(p.getId(),removed.getId(),clinic,"\"0\"",reason("Earlier correction"));jdbc.update("update case_sheet set status='FINALIZED' where id=?",parent);var before=jdbc.queryForList("select * from treatment_plan_item where treatment_plan_id=? order by id",p.getId());var history=jdbc.queryForList("select * from treatment_plan_item_audit where treatment_plan_id=? order by id",p.getId());var planBefore=jdbc.queryForMap("select * from treatment_plan where id=?",p.getId());removePlan(p.getId());var planAfter=jdbc.queryForMap("select * from treatment_plan where id=?",p.getId());for(String key:List.of("version","removed_at","removed_by","updated_at","updated_by")){planBefore.remove(key);planAfter.remove(key);}assertEquals(planBefore,planAfter);assertEquals(before,jdbc.queryForList("select * from treatment_plan_item where treatment_plan_id=? order by id",p.getId()));assertEquals(history,jdbc.queryForList("select * from treatment_plan_item_audit where treatment_plan_id=? order by id",p.getId()));var event=planAudit.findByClinicIdAndTreatmentPlanId(clinic,p.getId(),org.springframework.data.domain.PageRequest.of(0,20)).getContent().get(0);assertEquals(2,event.getRetainedItems().size());assertEquals(active.getId(),event.getRetainedItems().stream().filter(i->i.itemId().equals(active.getId())).findFirst().orElseThrow().itemId());assertEquals(new BigDecimal("12.35"),jdbc.queryForObject("select final_amount from treatment_plan where id=?",BigDecimal.class,p.getId()));}
 @Test void removalVersionsReasonsAndLifecycle(){var p=plan();assertEquals(428,assertThrows(TreatmentItemException.class,()->removal.remove(p.getId(),clinic,null,removalReason("Reason"))).status);for(String version:List.of("0","W/\"0\"","\"-1\"","\"999999999999999999999\""))assertEquals(400,assertThrows(TreatmentItemException.class,()->removal.remove(p.getId(),clinic,version,removalReason("Reason"))).status);assertEquals(412,assertThrows(TreatmentItemException.class,()->removal.remove(p.getId(),clinic,"\"1\"",removalReason("Reason"))).status);for(String reason:Arrays.asList(null," ","\u2003","x\n","🙂".repeat(1001)))assertEquals(400,assertThrows(TreatmentItemException.class,()->removal.remove(p.getId(),clinic,"\"0\"",removalReason(reason))).status);for(var status:TreatmentPlanStatus.values()){if(status==TreatmentPlanStatus.DRAFT)continue;jdbc.update("update treatment_plan set status=? where id=?",status.name(),p.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->removePlan(p.getId())).status);}var boundary=plan();removal.remove(boundary.getId(),clinic,"\"0\"",removalReason("🙂".repeat(1000)));}
 @Test void removedParentRejectsEveryExistingWriter(){var p=plan();var i=item(p.getId());removePlan(p.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->item(p.getId())).status);var header=new UpdateTreatmentPlanRequest();header.setClinicId(clinic);assertEquals(409,assertThrows(TreatmentItemException.class,()->plans.updateTreatmentPlan(p.getId(),header)).status);var status=new UpdateTreatmentPlanStatusRequest();status.setClinicId(clinic);status.setStatus(TreatmentPlanStatus.PRESENTED);assertEquals(409,assertThrows(TreatmentItemException.class,()->plans.updateTreatmentPlanStatus(p.getId(),status)).status);var itemStatus=new UpdateTreatmentPlanItemStatusRequest();itemStatus.setClinicId(clinic);itemStatus.setStatus(TreatmentPlanItemStatus.SCHEDULED);assertEquals(409,assertThrows(TreatmentItemException.class,()->plans.updateTreatmentPlanItemStatus(p.getId(),i.getId(),itemStatus)).status);assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.update(p.getId(),i.getId(),clinic,"\"0\"",update())).status);assertEquals(409,assertThrows(TreatmentItemException.class,()->entries.remove(p.getId(),i.getId(),clinic,"\"0\"",reason("Reason"))).status);var invoice=new com.dentalclinic.billing.dto.CreateInvoiceRequest();invoice.setClinicId(clinic);invoice.setTreatmentPlanId(p.getId());assertEquals(409,assertThrows(TreatmentItemException.class,()->invoices.createInvoice(invoice)).status);}
 @Test void planRemovalPermissionsAndIsolation(){var p=plan();for(String permission:List.of("TREATMENT_PLAN_VIEW","TREATMENT_PLAN_HISTORY_VIEW","ROLE_DOCTOR")){login(permission);assertThrows(AccessDeniedException.class,()->removalController.remove(p.getId(),clinic,"\"0\"",removalReason("Reason")));}UUID other=UUID.randomUUID();jdbc.update("insert into clinic(id,clinic_code,clinic_name) values (?,?,?)",other,other.toString(),"Other");actor=AppUser.builder().id(user).clinic(Clinic.builder().id(other).active(true).build()).build();login("TREATMENT_PLAN_EDIT");assertEquals(404,assertThrows(TreatmentItemException.class,()->removalController.remove(p.getId(),clinic,"\"0\"",removalReason("Reason"))).status);actor=AppUser.builder().id(user).build();login("TREATMENT_PLAN_EDIT");assertThrows(IllegalArgumentException.class,()->removalController.remove(p.getId(),null,"\"0\"",removalReason("Reason")));assertEquals(204,removalController.remove(p.getId(),clinic,"\"0\"",removalReason("Reason")).getStatusCode().value());}
 @Test void removalAuditFailureRollsBack(){var p=plan();item(p.getId());long version=revision(p.getId());String f="reject_plan_"+p.getId().toString().replace("-","");jdbc.execute("create function "+f+"() returns trigger language plpgsql as $$ begin if NEW.treatment_plan_id='"+p.getId()+"' then raise exception 'test plan audit failure'; end if; return NEW; end $$");jdbc.execute("create trigger "+f+" before insert on treatment_plan_audit for each row execute function "+f+"()");try{assertThrows(Exception.class,()->removePlan(p.getId()));assertEquals(version,revision(p.getId()));assertNull(jdbc.queryForObject("select removed_at from treatment_plan where id=?",java.sql.Timestamp.class,p.getId()));assertEquals(0,jdbc.queryForObject("select count(*) from treatment_plan_audit where treatment_plan_id=?",Integer.class,p.getId()));}finally{jdbc.execute("drop trigger "+f+" on treatment_plan_audit");jdbc.execute("drop function "+f+"()");}}
